glUniform1i(uniform_location, 0);
glActiveTexture(GL_TEXTURE0);
glBindTexture(GL_TEXTURE2D, my_texture);
This is put in a function in the pipeline to look this:
pipeline_.SetTexture("uniform_name", my_texture, 0);

